      --bg: #ffffff;
      --bg-page: #f3f4f6;
    }

    * {
      box-sizing: border-box;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
      background: var(--bg-page);
      color: var(--text);
      display: flex;
      justify-content: center;
      padding: 2rem;
      margin: 0;
    }

    .form-container {
      background: var(--bg);
      padding: 2rem;
      border-radius: 8px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
      width: 100%;
      max-width: 480px;
    }

    h1 {
      margin-top: 0;
      margin-bottom: 0.5rem;
      font-size: 1.5rem;
      font-weight: 700;
    }

    .legend {
      font-size: 0.875rem;
      color: var(--text-muted);
      margin-bottom: 1.5rem;
      margin-top: 0;
    }

    .form-field {
      margin-bottom: 1.5rem;
      display: flex;
      flex-direction: column;
    }

    label {
      font-weight: 600;
      margin-bottom: 0.375rem;
      font-size: 0.875rem;
    }

    .required-marker {
      color: var(--error);
      margin-left: 0.125rem;
    }

    input {
      padding: 0.625rem 0.75rem;
      border: 1px solid var(--border);
      border-radius: 4px;
      font-size: 1rem;
      line-height: 1.5;
      color: var(--text);
      background-color: var(--bg);
    }

    input:focus {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
      border-color: var(--primary);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
    }

    input[aria-invalid="true"]:focus {
      outline-color: var(--error);
    }

    .help-text {
      font-size: 0.875rem;
      color: var(--text-muted);
      margin-top: 0.375rem;
    }

    .error-text {
      font-size: 0.875rem;
      color: var(--error);
      margin-top: 0.375rem;
      display: none;
    }

    .error-text.visible {
      display: block;
    }

    button[type="submit"] {
      background: var(--primary);
      color: #ffffff;
      border: none;
      padding: 0.75rem 1rem;
      font-size: 1rem;
      border-radius: 4px;
      cursor: pointer;
      font-weight: 600;
      width: 100%;
      transition: background-color 0.15s ease-in-out;
    }

    button[type="submit"]:hover {
      background: var(--primary-hover);
    }

    button[type="submit"]:focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
    }

    .status-message {
      margin-top: 1rem;
      font-size: 0.875rem;
      font-weight: 600;
      display: none;
    }

    .status-message.success {
      display: block;
      color: #047857; /* Green 700 for contrast */
    }
  </style>
</head>
<body>
  <div class="form-container">
    <h1>Contact Support</h1>
    <p class="legend" id="form-legend"><span class="required-marker" aria-hidden="true">*</span> Indicates a required field</p>

    <form id="contact-form" novalidate>
      <div class="form-field">
        <label for="name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
        <input id="name" name="name" type="text" required autocomplete="name">
        <div id="name-error" class="error-text"></div>
      </div>

      <div class="form-field">
        <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
        <input id="email" name="email" type="email" required autocomplete="email">
        <div id="email-error" class="error-text"></div>
      </div>

      <div class="form-field">
        <label for="phone">Phone number (optional)</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" aria-describedby="phone-help">
        <div id="phone-help" class="help-text">Format: 123-456-7890</div>
        <div id="phone-error" class="error-text"></div>
      </div>

      <button type="submit">Submit request</button>
      <div id="status-live-region" class="status-message" aria-live="polite"></div>
    </form>
  </div>

  <script>
    document.addEventListener("DOMContentLoaded", () => {
      const form = document.getElementById("contact-form");
      const statusRegion = document.getElementById("status-live-region");

      form.addEventListener("submit", (e) => {
        e.preventDefault();

        // Reset status message
        statusRegion.className = "status-message";
        statusRegion.textContent = "";

        let firstInvalidField = null;

        // Reset all errors for fresh validation
        const errorTexts = form.querySelectorAll('.error-text');
        errorTexts.forEach(el => {
            el.classList.remove('visible');
            el.textContent = '';
        });

        const inputs = form.querySelectorAll('input');
        inputs.forEach(input => {
            input.removeAttribute('aria-invalid');
            let describedBy = input.getAttribute('aria-describedby') || '';
            const errorId = input.id + '-error';
            const describedByArray = describedBy.split(' ').filter(id => id !== errorId && id !== '');
            if (describedByArray.length > 0) {
                input.setAttribute('aria-describedby', describedByArray.join(' '));
            } else {
                input.removeAttribute('aria-describedby');
            }
        });

        // Validation for Full name
        const nameInput = document.getElementById("name");
        if (!nameInput.value.trim()) {
            showError(nameInput, "Error: Full name is required.");
            if (!firstInvalidField) firstInvalidField = nameInput;
        }

        // Validation for Email
        const emailInput = document.getElementById("email");
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailInput.value.trim()) {
            showError(emailInput, "Error: Email address is required.");
            if (!firstInvalidField) firstInvalidField = emailInput;
        } else if (!emailRegex.test(emailInput.value.trim())) {
            showError(emailInput, "Error: Enter a valid email address like name@example.com.");
            if (!firstInvalidField) firstInvalidField = emailInput;
        }

        // Validation for Phone (optional, but must be valid format if entered)
        const phoneInput = document.getElementById("phone");
        const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
        if (phoneInput.value.trim()) {
            if (!phoneRegex.test(phoneInput.value.trim())) {
                showError(phoneInput, "Error: Enter a valid phone number in the format 123-456-7890.");
                if (!firstInvalidField) firstInvalidField = phoneInput;
            }
        }

        // Handle validation results
        if (firstInvalidField) {
            firstInvalidField.focus();
        } else {
            // Form is valid - in a real app, send data to the server here
            statusRegion.textContent = "Your request has been submitted successfully.";
            statusRegion.classList.add("success");
            form.reset();
        }
      });

      function showError(input, message) {
        input.setAttribute("aria-invalid", "true");

        const errorId = input.id + "-error";
        const errorElement = document.getElementById(errorId);
        errorElement.textContent = message;
        errorElement.classList.add("visible");

        const existingDescribedBy = input.getAttribute("aria-describedby") || "";
        const describedByArray = existingDescribedBy.split(" ").filter(id => id !== "");
        if (!describedByArray.includes(errorId)) {
            describedByArray.push(errorId);
        }
        input.setAttribute("aria-describedby", describedByArray.join(" "));
      }

      // Clear specific error dynamically on input modification
      form.addEventListener("input", (e) => {
         if (e.target.tagName === 'INPUT' && e.target.getAttribute('aria-invalid') === 'true') {
             e.target.removeAttribute('aria-invalid');
             const errorId = e.target.id + '-error';
             const errorElement = document.getElementById(errorId);
             if (errorElement) {
                 errorElement.classList.remove('visible');
                 errorElement.textContent = '';
             }
             let describedBy = e.target.getAttribute('aria-describedby') || '';
             const describedByArray = describedBy.split(' ').filter(id => id !== errorId && id !== '');
             if (describedByArray.length > 0) {
                 e.target.setAttribute('aria-describedby', describedByArray.join(' '));
             } else {
                 e.target.removeAttribute('aria-describedby');
             }
         }
      });
    });
  </script>
</body>
